let _markdown = "\n\nOverview [#overview]\n\n<FeedbackBlock id=\"e895f37f10971ad2\" body=\"You can run fumadocs-mdx to generate types & entry files (the .source folder).\">\n  You can run `fumadocs-mdx` to generate types & entry files (the `.source` folder).\n</FeedbackBlock>\n\n<FeedbackBlock id=\"e1f5d9a920d34660\" body=\"Optionally, you can run it in post install to ensure types are generated when initializing the project.\">\n  Optionally, you can run it in post install to ensure types are generated when initializing the project.\n</FeedbackBlock>\n\n```json title=\"package.json\"\n{\n  \"scripts\": {\n    \"postinstall\": \"fumadocs-mdx\"\n  }\n}\n```\n\n<FeedbackBlock id=\"9b93727e56b50dd6\" body=\"If your project uses a custom path for configuration file or output directory, you can provide them as command arguments:\">\n  If your project uses a custom path for configuration file or output directory, you can provide them as command arguments:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npx fumadocs-mdx \"config-path\" \"output-dir\"\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm dlx fumadocs-mdx \"config-path\" \"output-dir\"\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn dlx fumadocs-mdx \"config-path\" \"output-dir\"\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun x fumadocs-mdx \"config-path\" \"output-dir\"\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"22ee6ff4649d769d\" body=\"config-path: Fumadocs MDX config file, default to source.config.ts.output-dir: Directory of generated files, default to .source.\">\n  * `config-path`: Fumadocs MDX config file, default to `source.config.ts`.\n  * `output-dir`: Directory of generated files, default to `.source`.\n</FeedbackBlock>\n";
